window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2091001af2b3b465"]={"versions": [{"id": "FIG-2091001af2b3b465", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Dienstaufrufs im AUTOSAR-Kryptografie-Stack (Classic Platform). Das Diagramm veranschaulicht den vertikalen Kontroll- und Datenfluss von der anwendungsnahen Schicht über den Crypto Service Manager (<code>Csm</code>) und das Crypto Interface (<code>CryIf</code>) bis hinunter zum Crypto Driver (<code>Crypto</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>:Application</code>: Aufrufende Entität (z. B. SW-C oder Systemdienst).\n</li><li><code>«module» :Csm</code>: Crypto Service Manager als standardisierte Service-Schicht.\n</li><li><code>«module» :CryIf</code>: Crypto Interface als Abstraktionsschicht zwischen CSM und kryptografischen Hardware-/Software-Treibern.\n</li><li><code>«module» :Crypto</code>: Crypto Driver (z. B. Crypto Driver Object / Hardware-Krypto-Treiber).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchrone Aufrufoperationen <code>&lt;Service&gt;()</code> über alle Ebenen (<code>:Application</code> -&gt; <code>:Csm</code> -&gt; <code>:CryIf</code> -&gt; <code>:Crypto</code>).\n</li><li>Synchrone Rücksprungnachrichten <code>return with result()</code> in umgekehrter Reihenfolge (<code>:Crypto</code> -&gt; <code>:CryIf</code> -&gt; <code>:Csm</code> -&gt; <code>:Application</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf eines synchronen Aufrufs:</p>\n<ol class=\"fig-list\"><li><code>:Application</code> initiiert die kryptografische Operation durch den Aufruf von <code>&lt;Service&gt;()</code> am <code>:Csm</code>.\n</li><li><code>:Csm</code> leitet die Anforderung synchron mittels <code>&lt;Service&gt;()</code> an <code>:CryIf</code> weiter.\n</li><li><code>:CryIf</code> leitet den Aufruf über <code>&lt;Service&gt;()</code> synchron an das zuständige Treiber-Modul <code>:Crypto</code> weiter.\n</li><li><code>:Crypto</code> führt die Operation aus und liefert das Ergebnis synchron mittels <code>return with result()</code> an <code>:CryIf</code> zurück.\n</li><li><code>:CryIf</code> reicht das Ergebnis über <code>return with result()</code> an <code>:Csm</code> weiter.\n</li><li><code>:Csm</code> gibt das Endergebnis über <code>return with result()</code> an <code>:Application</code> zurück. Während des gesamten Durchlaufs blockiert jede aufrufende Instanz bis zum Eintreffen der jeweiligen Rückgabe (durchgehende Ausführungsbalken / Execution Specifications).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Interaktionskaskade für synchrone CSM-Dienste. Implementierer von CSM, CryIf und Crypto-Treibern müssen sicherstellen, dass Aufrufe im synchronen Modus blockierend abgearbeitet werden und der Aufrufkontext bis zum Abschluss der Operation im Crypto Driver verharrt. Es erfolgt keine asynchrone Entkopplung über Polling-Zyklen (<code>MainFunction</code>) oder Callback-Benachrichtigungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-38bf98a5be56f819", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Dienstaufrufs im AUTOSAR-Kryptografie-Stack (Classic Platform). Das Diagramm veranschaulicht den vertikalen Kontroll- und Datenfluss von der anwendungsnahen Schicht über den Crypto Service Manager (<code>Csm</code>) und das Crypto Interface (<code>CryIf</code>) bis hinunter zum Crypto Driver (<code>Crypto</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>:Application</code>: Aufrufende Entität (z. B. SW-C oder Systemdienst).\n</li><li><code>«module» :Csm</code>: Crypto Service Manager als standardisierte Service-Schicht.\n</li><li><code>«module» :CryIf</code>: Crypto Interface als Abstraktionsschicht zwischen CSM und kryptografischen Hardware-/Software-Treibern.\n</li><li><code>«module» :Crypto</code>: Crypto Driver (z. B. Crypto Driver Object / Hardware-Krypto-Treiber).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchrone Aufrufoperationen <code>&lt;Service&gt;()</code> über alle Ebenen (<code>:Application</code> -&gt; <code>:Csm</code> -&gt; <code>:CryIf</code> -&gt; <code>:Crypto</code>).\n</li><li>Synchrone Rücksprungnachrichten <code>return with result()</code> in umgekehrter Reihenfolge (<code>:Crypto</code> -&gt; <code>:CryIf</code> -&gt; <code>:Csm</code> -&gt; <code>:Application</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf eines synchronen Aufrufs:</p>\n<ol class=\"fig-list\"><li><code>:Application</code> initiiert die kryptografische Operation durch den Aufruf von <code>&lt;Service&gt;()</code> am <code>:Csm</code>.\n</li><li><code>:Csm</code> leitet die Anforderung synchron mittels <code>&lt;Service&gt;()</code> an <code>:CryIf</code> weiter.\n</li><li><code>:CryIf</code> leitet den Aufruf über <code>&lt;Service&gt;()</code> synchron an das zuständige Treiber-Modul <code>:Crypto</code> weiter.\n</li><li><code>:Crypto</code> führt die Operation aus und liefert das Ergebnis synchron mittels <code>return with result()</code> an <code>:CryIf</code> zurück.\n</li><li><code>:CryIf</code> reicht das Ergebnis über <code>return with result()</code> an <code>:Csm</code> weiter.\n</li><li><code>:Csm</code> gibt das Endergebnis über <code>return with result()</code> an <code>:Application</code> zurück. Während des gesamten Durchlaufs blockiert jede aufrufende Instanz bis zum Eintreffen der jeweiligen Rückgabe (durchgehende Ausführungsbalken / Execution Specifications).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Interaktionskaskade für synchrone CSM-Dienste. Implementierer von CSM, CryIf und Crypto-Treibern müssen sicherstellen, dass Aufrufe im synchronen Modus blockierend abgearbeitet werden und der Aufrufkontext bis zum Abschluss der Operation im Crypto Driver verharrt. Es erfolgt keine asynchrone Entkopplung über Polling-Zyklen (<code>MainFunction</code>) oder Callback-Benachrichtigungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-aae019390a2e2798", "releases": ["R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Dienstaufrufs im AUTOSAR-Kryptografie-Stack (Classic Platform). Das Diagramm veranschaulicht den vertikalen Kontroll- und Datenfluss von der anwendungsnahen Schicht über den Crypto Service Manager (<code>Csm</code>) und das Crypto Interface (<code>CryIf</code>) bis hinunter zum Crypto Driver (<code>Crypto</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>:Application</code>: Aufrufende Entität (z. B. SW-C oder Systemdienst).\n</li><li><code>«module» :Csm</code>: Crypto Service Manager als standardisierte Service-Schicht.\n</li><li><code>«module» :CryIf</code>: Crypto Interface als Abstraktionsschicht zwischen CSM und kryptografischen Hardware-/Software-Treibern.\n</li><li><code>«module» :Crypto</code>: Crypto Driver (z. B. Crypto Driver Object / Hardware-Krypto-Treiber).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Synchrone Aufrufoperationen <code>&lt;Service&gt;()</code> über alle Ebenen (<code>:Application</code> -&gt; <code>:Csm</code> -&gt; <code>:CryIf</code> -&gt; <code>:Crypto</code>).\n</li><li>Synchrone Rücksprungnachrichten <code>return with result()</code> in umgekehrter Reihenfolge (<code>:Crypto</code> -&gt; <code>:CryIf</code> -&gt; <code>:Csm</code> -&gt; <code>:Application</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf eines synchronen Aufrufs:</p>\n<ol class=\"fig-list\"><li><code>:Application</code> initiiert die kryptografische Operation durch den Aufruf von <code>&lt;Service&gt;()</code> am <code>:Csm</code>.\n</li><li><code>:Csm</code> leitet die Anforderung synchron mittels <code>&lt;Service&gt;()</code> an <code>:CryIf</code> weiter.\n</li><li><code>:CryIf</code> leitet den Aufruf über <code>&lt;Service&gt;()</code> synchron an das zuständige Treiber-Modul <code>:Crypto</code> weiter.\n</li><li><code>:Crypto</code> führt die Operation aus und liefert das Ergebnis synchron mittels <code>return with result()</code> an <code>:CryIf</code> zurück.\n</li><li><code>:CryIf</code> reicht das Ergebnis über <code>return with result()</code> an <code>:Csm</code> weiter.\n</li><li><code>:Csm</code> gibt das Endergebnis über <code>return with result()</code> an <code>:Application</code> zurück. Während des gesamten Durchlaufs blockiert jede aufrufende Instanz bis zum Eintreffen der jeweiligen Rückgabe (durchgehende Ausführungsbalken / Execution Specifications).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Interaktionskaskade für synchrone CSM-Dienste. Implementierer von CSM, CryIf und Crypto-Treibern müssen sicherstellen, dass Aufrufe im synchronen Modus blockierend abgearbeitet werden und der Aufrufkontext bis zum Abschluss der Operation im Crypto Driver verharrt. Es erfolgt keine asynchrone Entkopplung über Polling-Zyklen (<code>MainFunction</code>) oder Callback-Benachrichtigungen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2091001af2b3b465", "to": "FIG-38bf98a5be56f819", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-38bf98a5be56f819", "to": "FIG-aae019390a2e2798", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
